public class Point{public float x_,z_;}public class Player{public Point pos_=new Point();}public class Manager{public int state_;}public class UserData{public Manager gm_=new Manager();}
public class Semantics{public UserData udat_=new UserData();public Point pos_=new Point();public int sink;void Use(){sink++;}public void Before(Player player,bool coatOut_ok){if ((udat_.gm_.state_ != 0 && coatOut_ok) || (!(pos_.z_ >= 900f) && !(pos_.z_ <= -900f) && !(pos_.x_ <= -450f) && !(pos_.x_ >= 450f) && !(player.pos_.z_ >= 900f) && !(player.pos_.z_ <= -900f) && !(player.pos_.x_ <= -450f) && !(player.pos_.x_ >= 450f))){Use();}}public void Candidate(Player player,bool coatOut_ok){if (udat_.gm_.state_ == 0 || !coatOut_ok)
{
if (pos_.z_ >= 900f || pos_.z_ <= -900f || pos_.x_ <= -450f || pos_.x_ >= 450f) { return; }
if (player.pos_.z_ >= 900f || player.pos_.z_ <= -900f || player.pos_.x_ <= -450f || player.pos_.x_ >= 450f) { return; }
}
Use();}public void Control(Player player,bool coatOut_ok){if(!(udat_.gm_.state_!=0&&coatOut_ok)){if(pos_.z_>=900f||pos_.z_<=-900f||pos_.x_<=-450f||pos_.x_>=450f){return;}if(player.pos_.z_>=900f||player.pos_.z_<=-900f||player.pos_.x_<=-450f||player.pos_.x_>=450f){return;}}Use();}public void Wrong(Player player,bool coatOut_ok){if(!(udat_.gm_.state_!=0&&coatOut_ok)){if(!(pos_.z_<900f&&pos_.z_>-900f&&pos_.x_>-450f&&pos_.x_<450f)){return;}if(player.pos_.z_>=900f||player.pos_.z_<=-900f||player.pos_.x_<=-450f||player.pos_.x_>=450f){return;}}Use();}}public class Runner{public static int Main(){float[] values={-1000f,-900f,-450f,0f,450f,900f,1000f,float.NaN,float.NegativeInfinity,float.PositiveInfinity};int bad=0,wrong=0,cases=0;foreach(float a in values)foreach(float b in values)foreach(float c in values)foreach(float d in values)for(int state=0;state<2;state++)for(int allow=0;allow<2;allow++){Semantics f=new Semantics();f.udat_.gm_.state_=state;f.pos_.x_=a;f.pos_.z_=b;Player p=new Player();p.pos_.x_=c;p.pos_.z_=d;f.Before(p,allow!=0);int first=f.sink;f.sink=0;f.Candidate(p,allow!=0);int second=f.sink;f.sink=0;f.Control(p,allow!=0);int third=f.sink;f.sink=0;f.Wrong(p,allow!=0);if(first!=second||second!=third)bad++;if(first!=f.sink)wrong++;cases++;}System.Console.WriteLine(cases+":"+bad+":"+wrong);return bad==0&&wrong>0?0:1;}}